_OUTPUT_JSON = False


def section(title):
    stream = sys.stderr if _OUTPUT_JSON else sys.stdout
    print(f"\n=== {title} ===", file=stream)


def status(mark, message):
    stream = sys.stderr if _OUTPUT_JSON else sys.stdout
    print(f"  [{mark}] {message}", file=stream)


def _emit_json(args, result):
    if getattr(args, "json", False):
        print(json.dumps(result, ensure_ascii=False, indent=2))


def is_windows():
    return os.name == "nt"


def codex_home_from_env():
    override = os.environ.get("CODEX_HOME")
    if override:
        return pathlib.Path(override).expanduser()
    return pathlib.Path.home() / ".codex"


def sha256_bytes(data):
    return hashlib.sha256(data).hexdigest()


def sha256_of(path):
    return sha256_bytes(path.read_bytes())


def write_bytes_atomically(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
    try:
        with temporary.open("wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    finally:
        temporary.unlink(missing_ok=True)


def write_text_utf8(path, text):
    write_bytes_atomically(path, text.encode("utf-8"))


def read_text_utf8(path):
    return path.read_text(encoding="utf-8")


def payload_bytes(rel):
    return base64.b64decode(_PAYLOAD_B64[rel])


def payload_text(rel):
    return payload_bytes(rel).decode("utf-8")


def state_dir(codex_home):
    return codex_home / STATE_DIR_NAME


def state_path(codex_home):
    return state_dir(codex_home) / "state.json"


def load_state(codex_home):
    path = state_path(codex_home)
    if not path.exists():
        return {}
    try:
        data = json.loads(read_text_utf8(path))
    except (json.JSONDecodeError, UnicodeDecodeError, OSError):
        return {}
    return data if isinstance(data, dict) else {}


def save_state(codex_home, state):
    state_path(codex_home).parent.mkdir(parents=True, exist_ok=True)
    write_text_utf8(
        state_path(codex_home),
        json.dumps(state, ensure_ascii=False, indent=2) + "\n",
    )


def load_opencode_go_credentials():
    """Return (base_url, api_key) from ~/.kimi-code/config.toml, or (None, None)."""
    kimi_config = pathlib.Path.home() / ".kimi-code" / "config.toml"
    if not kimi_config.exists():
        return None, None
    try:
        data = tomllib.loads(read_text_utf8(kimi_config))
    except (tomllib.TOMLDecodeError, UnicodeDecodeError):
        return None, None
    provider = data.get("providers", {}).get("opencode-go", {})
    api_key = provider.get("api_key")
    base_url = provider.get("base_url")
    if api_key and base_url:
        return base_url, api_key
    return None, None


def toml_string(value):
    """Return a TOML basic-string literal (with surrounding quotes) for value.

    Uses JSON string escaping, which is a valid subset of TOML basic strings:
    ``"``, ``\\``, control characters, and other specials are escaped, so a
    credential or base URL can never produce malformed TOML.
    """
    return json.dumps(str(value), ensure_ascii=False)


def _existing_agent_credentials(codex_home):
    """Return (base_url, provider_lines) preserved from the installed agent file.

    Preserves either an ``experimental_bearer_token`` or an ``env_key``
    credential so a noninteractive update never silently changes the
    credential mechanism. Both are re-emitted with TOML escaping.
    """
    path = codex_home / AGENT_FILENAME
    if not path.exists():
        return None
    try:
        data = tomllib.loads(read_text_utf8(path))
    except (tomllib.TOMLDecodeError, UnicodeDecodeError):
        return None
    provider = data.get("model_providers", {}).get("deepseek", {})
    if not isinstance(provider, dict):
        return None
    base_url = provider.get("base_url")
    token = provider.get("experimental_bearer_token")
    if token:
        return base_url, f"experimental_bearer_token = {toml_string(token)}"
    env_key = provider.get("env_key")
    if env_key:
        return base_url, f"env_key = {toml_string(env_key)}"
    return None


def _prompt_line(prompt, stream):
    """Print ``prompt`` to ``stream`` and read one line from stdin.

    ``input(prompt)`` always writes the prompt to stdout; printing it
    explicitly keeps stdout free for the single JSON document in --json mode.
    """
    print(prompt, end="", file=stream, flush=True)
    return input()


def resolve_credentials(codex_home):
    """Resolve (base_url, provider_lines, source_label).

    Explicit interactive input wins. A noninteractive run never silently
    replaces an existing credential token: when the installed agent file
    already has one, it is preserved together with its base URL. Otherwise fall
    back to ~/.kimi-code opencode-go, then DEEPSEEK_API_KEY.
    """
    existing = _existing_agent_credentials(codex_home)
    user_base = None
    user_key = None
    if sys.stdin.isatty():
        # input(prompt) writes the prompt to stdout, which would pollute the
        # single JSON document in --json mode; print the prompt explicitly so
        # it can be routed to stderr while still reading from the real TTY.
        prompt_stream = sys.stderr if _OUTPUT_JSON else sys.stdout
        try:
            print(
                "Credential input (press Enter to auto-resolve):",
                file=prompt_stream,
            )
            hint = (
                existing[0]
                if existing and existing[0]
                else "https://api.deepseek.com"
            )
            user_base = (
                _prompt_line(f"  base URL [{hint}]: ", prompt_stream).strip()
                or None
            )
            user_key = _prompt_line(
                "  API key (visible while typing; Enter to auto-resolve): ",
                prompt_stream,
            ).strip() or None
        except EOFError:
            # Closed/absent stdin (piped, CI, spawned): fall back to automatic
            # resolution instead of aborting the whole install.
            user_base = None
            user_key = None
    if user_key:
        base = user_base or "https://api.deepseek.com"
        return base, f"experimental_bearer_token = {toml_string(user_key)}", "user input"
    if existing:
        base = user_base or existing[0] or "https://api.deepseek.com"
        label = (
            "existing env_key (preserved)"
            if "env_key" in existing[1]
            else "existing agent token (preserved)"
        )
        return base, existing[1], label
    if user_base:
        return user_base, f"env_key = {toml_string('DEEPSEEK_API_KEY')}", "env var DEEPSEEK_API_KEY (official endpoint)"
    kimi_base, kimi_key = load_opencode_go_credentials()
    if kimi_base and kimi_key:
        return kimi_base, f"experimental_bearer_token = {toml_string(kimi_key)}", "~/.kimi-code [providers.opencode-go]"
    return "https://api.deepseek.com", f"env_key = {toml_string('DEEPSEEK_API_KEY')}", "env var DEEPSEEK_API_KEY (official endpoint)"


def agent_toml_content(base_url, provider_lines):
    return AGENT_TOML_TEMPLATE.format(
        base_url=toml_string(base_url), provider_lines=provider_lines
    )


def hook_replacement_group(codex_home, python_executable):
    script = codex_home / "hooks" / "codex-deepseek-subagent" / "plaintext_handoff.py"
    posix_command = f"python3 -X utf8 {shlex.quote(str(script))} --mode hook"
    windows_command = subprocess.list2cmdline(
        [python_executable, "-X", "utf8", str(script), "--mode", "hook"]
    )
    return {
        "matcher": HOOK_GROUP_MATCHER,
        "hooks": [
            {
                "type": "command",
                "command": posix_command,
                "commandWindows": windows_command,
                "timeout": HOOK_TIMEOUT_SECONDS,
                "statusMessage": HOOK_STATUS_MESSAGE,
                "additionalContextLimit": HOOK_ADDITIONAL_CONTEXT_LIMIT,
            }
        ],
    }


def hook_definition_sha256(group):
    return sha256_bytes(
        json.dumps(group, sort_keys=True, separators=(",", ":")).encode("utf-8")
    )


def _validate_hooks_shape(document):
    """Validate a parsed hooks.json container; raise ValueError when malformed.

    Uses the same "must be a JSON array" convention as merge_hooks so install,
    remove, and status all refuse structurally invalid hooks documents with a
    clean controlled error instead of an AttributeError traceback.
    """
    if not isinstance(document, dict):
        raise ValueError("hooks.json must contain a top-level JSON object")
    hooks = document.get("hooks")
    if "hooks" in document and not isinstance(hooks, dict):
        raise ValueError("hooks.json 'hooks' must be a JSON object")
    groups = hooks.get("SubagentStart", []) if hooks is not None else []
    if not isinstance(groups, list):
        raise ValueError("hooks.json SubagentStart must be a JSON array")


def merge_hooks(existing, replacement):
    """Merge the owned SubagentStart group; return (document, changed, previous).

    ``existing`` may be None (no hooks.json yet). Unrelated hook groups are
    preserved. ``changed`` is True when the owned group differs from
    ``replacement`` (or the file did not exist).
    """
    if existing is None:
        document = {
            "description": HOOK_DESCRIPTION,
            "hooks": {"SubagentStart": [replacement]},
        }
        return document, True, None
    document = existing
    _validate_hooks_shape(document)
    groups = document.setdefault("hooks", {}).setdefault("SubagentStart", [])
    previous = None
    for index, group in enumerate(groups):
        if isinstance(group, dict) and group.get("matcher") == replacement["matcher"]:
            previous = group
            groups[index] = replacement
            break
    else:
        groups.append(replacement)
    return document, previous != replacement, previous


def merge_config(text):
    """Idempotently ensure [shell_environment_policy.set]; returns (text, changed)."""
    lines = text.splitlines()
    try:
        section_index = next(
            index for index, line in enumerate(lines) if line.strip() == CONFIG_SECTION
        )
    except StopIteration:
        if lines and lines[-1].strip():
            lines.append("")
        lines.append(CONFIG_SECTION)
        section_index = len(lines) - 1
    end_index = len(lines)
    for index in range(section_index + 1, len(lines)):
        stripped = lines[index].strip()
        if stripped.startswith("[") and stripped.endswith("]"):
            end_index = index
            break
    for key, value in ENVIRONMENT_VALUES.items():
        replacement = f'{key} = "{value}"'
        found = None
        for index in range(section_index + 1, end_index):
            if lines[index].split("=", 1)[0].strip() == key:
                found = index
                break
        if found is not None:
            lines[found] = replacement
        else:
            lines.insert(end_index, replacement)
            end_index += 1
    new_text = "\n".join(lines).rstrip() + "\n"
    return new_text, new_text != text


def agents_block_text():
    """Extract the marked block from the payload AGENTS asset."""
    text = payload_text("agents/codex_AGENTS_block.md")
    start_marker = f"<!-- {AGENTS_BLOCK_MARKER}:start -->"
    end_marker = f"<!-- {AGENTS_BLOCK_MARKER}:end -->"
    start_index = text.find(start_marker)
    end_index = text.find(end_marker, start_index)
    if start_index < 0 or end_index < 0:
        raise ValueError(
            f"payload agents/codex_AGENTS_block.md must contain both {AGENTS_BLOCK_MARKER} markers"
        )
    end_of_line = text.find("\n", end_index)
    if end_of_line < 0:
        end_of_line = len(text)
    else:
        end_of_line += 1
    block = text[start_index:end_of_line]
    if not block.endswith("\n"):
        block += "\n"
    return block


def strip_legacy_agents_block(existing):
    """Remove every complete legacy codex-deepseek-subagent marker region."""
    start_marker = f"<!-- {LEGACY_AGENTS_BLOCK_MARKER}:start -->"
    end_marker = f"<!-- {LEGACY_AGENTS_BLOCK_MARKER}:end -->"
    while True:
        start_index = existing.find(start_marker)
        if start_index < 0:
            return existing
        end_index = existing.find(end_marker, start_index)
        if end_index < 0:
            raise ValueError(
                f"AGENTS.md has a dangling {LEGACY_AGENTS_BLOCK_MARKER} start marker"
            )
        end_of_line = existing.find("\n", end_index)
        if end_of_line < 0:
            end_of_line = len(existing)
        else:
            end_of_line += 1
        before = existing[:start_index]
        after = existing[end_of_line:]
        if before and not before.endswith("\n"):
            before += "\n"
        while after.startswith("\n"):
            after = after[1:]
        existing = before + after


def merge_agents(existing, block):
    """Idempotently merge the marked block; returns (text, changed).

    Legacy codex-deepseek-subagent regions are migrated away first; content
    outside the marked blocks is preserved byte-for-byte.
    """
    existing = strip_legacy_agents_block(existing)
    start_marker = f"<!-- {AGENTS_BLOCK_MARKER}:start -->"
    end_marker = f"<!-- {AGENTS_BLOCK_MARKER}:end -->"
    start_index = existing.find(start_marker)
    if start_index >= 0:
        end_index = existing.find(end_marker, start_index)
        if end_index < 0:
            raise ValueError(f"AGENTS.md has a dangling {AGENTS_BLOCK_MARKER} start marker")
        end_of_line = existing.find("\n", end_index)
        if end_of_line < 0:
            end_of_line = len(existing)
        else:
            end_of_line += 1
        before = existing[:start_index]
        after = existing[end_of_line:]
        if before and not before.endswith("\n"):
            before += "\n"
        while after.startswith("\n"):
            after = after[1:]
        merged = before + block + after
    else:
        merged = existing
        if merged and not merged.endswith("\n"):
            merged += "\n"
        merged += block
    return merged, merged != existing


def default_backup_root():
    return pathlib.Path.home() / ".codex-backups" / "codex-deepseek-subagent"


def backup_root_from_args(args):
    if getattr(args, "backup_dir", None):
        return pathlib.Path(args.backup_dir).expanduser()
    return default_backup_root()

def create_backup(codex_home, backup_root, action="install"):
    """Absence-aware snapshot of every managed file plus installer state.

    A failure mid-snapshot removes the partial backup directory before
    re-raising, so a failed backup never leaves a half-written snapshot.
    """
    stamp = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S-%f")
    backup_dir = backup_root / stamp
    try:
        files_dir = backup_dir / "files"
        manifest = {
            "format_version": 2,
            "tool": TOOL_NAME,
            "payload_version": PAYLOAD_VERSION,
            "created_at": stamp,
            "platform": os.name,
            "codex_home": str(codex_home),
            "action": action,
            "files": {},
            "state": {},
        }
        for rel in MANAGED_FILES:
            source = codex_home / rel
            if not source.exists():
                manifest["files"][rel] = {"absent": True}
                continue
            destination = files_dir / rel
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, destination)
            manifest["files"][rel] = {"sha256": sha256_of(source)}
        state_file = state_path(codex_home)
        if state_file.exists():
            destination = files_dir / STATE_DIR_NAME / "state.json"
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(state_file, destination)
            manifest["state"] = {"sha256": sha256_of(state_file)}
        else:
            manifest["state"] = {"absent": True}
        write_text_utf8(
            backup_dir / "manifest.json",
            json.dumps(manifest, ensure_ascii=False, indent=2) + "\n",
        )
    except Exception:
        shutil.rmtree(backup_dir, ignore_errors=True)
        raise
    return backup_dir


def list_backups(backup_root):
    if not backup_root.exists():
        return []
    return sorted(
        (entry for entry in backup_root.iterdir() if entry.is_dir()),
        key=lambda p: p.name,
        reverse=True,
    )


def _plan_restore(backup_dir, codex_home, yes, force):
    """Return (plan, refused, manifest) without writing anything."""
    manifest_path = backup_dir / "manifest.json"
    if not manifest_path.exists():
        return [], [], None
    manifest = json.loads(read_text_utf8(manifest_path))
    state = load_state(codex_home)
    files = manifest.get("files", {})
    plan = []
    refused = []
    for rel in MANAGED_FILES:
        entry = files.get(rel)
        if entry is None:
            continue
        target = codex_home / rel
        if entry.get("absent"):
            if not target.exists():
                continue
            if sha256_of(target) == state.get("files", {}).get(rel) or force or yes:
                plan.append((rel, "delete"))
            else:
                refused.append(rel)
            continue
        source = backup_dir / "files" / rel
        if not source.exists():
            continue
        if target.exists():
            current_sha = sha256_of(target)
            if current_sha == entry.get("sha256"):
                continue
            owned = current_sha == state.get("files", {}).get(rel)
            if owned or yes or force:
                plan.append((rel, "overwrite"))
            else:
                refused.append(rel)
        else:
            plan.append((rel, "overwrite"))
    return plan, refused, manifest


def restore_backup(backup_dir, codex_home, yes=False, force=False, dry_run=False):
    """Restore an exact pre-change snapshot; returns a result dict."""
    plan, refused, manifest = _plan_restore(backup_dir, codex_home, yes, force)
    if manifest is None:
        status("FAIL", f"no manifest.json in {backup_dir}")
        return {"restored": [], "deleted": [], "skipped": [], "refused": []}
    if refused:
        for rel in refused:
            status("FAIL", f"{rel}: restore refused; rerun with --yes/--force")
        return {"restored": [], "deleted": [], "skipped": [], "refused": refused}
    restored = []
    deleted = []
    if dry_run:
        for rel, action in plan:
            status(
                "DRY",
                f"{rel} would be {'deleted' if action == 'delete' else 'restored'}",
            )
        return {"restored": [], "deleted": [], "skipped": [], "refused": []}
    for rel, action in plan:
        target = codex_home / rel
        if action == "delete":
            target.unlink(missing_ok=True)
            status("DELETED", rel)
            deleted.append(rel)
        else:
            source = backup_dir / "files" / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, target)
            status("RESTORED", rel)
            restored.append(rel)
    state_entry = manifest.get("state", {"absent": True})
    if state_entry.get("absent"):
        shutil.rmtree(state_dir(codex_home), ignore_errors=True)
    else:
        source = backup_dir / "files" / STATE_DIR_NAME / "state.json"
        if source.exists():
            destination = state_path(codex_home)
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, destination)
    prune_owned_dirs(codex_home, dry_run=False)
    section("Post-restore validation")
    validate(codex_home)
    status(
        "NOTE",
        "restore is an exact snapshot; re-run the installer (default or --update) "
        "to resync the managed content",
    )
    return {"restored": restored, "deleted": deleted, "skipped": [], "refused": []}


def _hooks_document_has_unrelated_content(document):
    """True when a hooks.json contains anything the installer does not own.

    The installer only owns the ``description`` value it writes and the
    ``SubagentStart`` group whose matcher is HOOK_GROUP_MATCHER. Any other
    top-level key, a different description, another hook category, or a
    remaining SubagentStart group counts as unrelated content.
    """
    if not isinstance(document, dict):
        return True
    for key in document:
        if key not in ("description", "hooks"):
            return True
    if "description" in document and document["description"] != HOOK_DESCRIPTION:
        return True
    hooks = document.get("hooks")
    if hooks is not None:
        if not isinstance(hooks, dict):
            return True
        for category in hooks:
            if category != "SubagentStart":
                return True
        if hooks.get("SubagentStart"):
            return True
    return False


def remove_hook_group(codex_home, state, dry_run):
    """Remove the owned SubagentStart group; returns absent/noop/delete/update.

    The whole file is unlinked only when it is provably an installer-created
    shell: the current bytes match the recorded state hash AND removing the
    owned group leaves no unrelated content. A pre-existing hooks.json that was
    merged at install time therefore keeps its unrelated bytes: the owned group
    is surgically removed instead.
    """
    target = codex_home / "hooks.json"
    if not target.exists():
        return "absent"
    document = json.loads(read_text_utf8(target))
    _validate_hooks_shape(document)
    groups = document.get("hooks", {}).get("SubagentStart", [])
    new_groups = [
        group
        for group in groups
        if not (isinstance(group, dict) and group.get("matcher") == HOOK_GROUP_MATCHER)
    ]
    if len(new_groups) == len(groups):
        status("OK", "hooks.json has no owned v4_flash_worker group")
        return "noop"
    remaining = dict(document)
    if new_groups:
        remaining.setdefault("hooks", {})["SubagentStart"] = new_groups
    else:
        hooks = remaining.get("hooks")
        if isinstance(hooks, dict):
            hooks.pop("SubagentStart", None)
            if not hooks:
                remaining.pop("hooks", None)
    owned_file = sha256_of(target) == state.get("files", {}).get("hooks.json")
    delete_eligible = owned_file and not _hooks_document_has_unrelated_content(
        remaining
    )
    if dry_run:
        if delete_eligible:
            status("DRY", "hooks.json would be deleted (installer-created)")
        else:
            status("DRY", "hooks.json owned group would be removed")
        return "delete" if delete_eligible else "update"
    if delete_eligible:
        target.unlink()
        status("REMOVED", "hooks.json")
        return "delete"
    write_text_utf8(
        target, json.dumps(remaining, ensure_ascii=False, indent=2) + "\n"
    )
    status("REMOVED", "hooks.json v4_flash_worker group (unrelated hooks preserved)")
    return "update"


def remove_config_owned(codex_home, state, dry_run):
    """Remove owned [shell_environment_policy.set] keys; returns a file outcome."""
    target = codex_home / "config.toml"
    if not target.exists():
        return "absent"
    text = read_text_utf8(target)
    lines = text.splitlines()
    try:
        section_index = next(
            index for index, line in enumerate(lines) if line.strip() == CONFIG_SECTION
        )
    except StopIteration:
        status("OK", "config.toml has no [shell_environment_policy.set] section")
        return "noop"
    end_index = len(lines)
    for index in range(section_index + 1, len(lines)):
        stripped = lines[index].strip()
        if stripped.startswith("[") and stripped.endswith("]"):
            end_index = index
            break
    body = lines[section_index + 1 : end_index]
    owned_keys = set(ENVIRONMENT_VALUES)
    owned_lines = [
        line for line in body if line.split("=", 1)[0].strip() in owned_keys
    ]
    user_lines = [
        line for line in body
        if line.strip() and line.split("=", 1)[0].strip() not in owned_keys
    ]
    if not owned_lines:
        status("OK", "config.toml has no owned shell_environment_policy keys")
        return "noop"
    if user_lines:
        kept_body = [
            line for line in body if line.split("=", 1)[0].strip() not in owned_keys
        ]
        new_lines = lines[: section_index + 1] + kept_body + lines[end_index:]
        new_text = "\n".join(new_lines).rstrip() + "\n"
    else:
        new_lines = lines[:section_index]
        if new_lines and new_lines[-1].strip() == "":
            new_lines = new_lines[:-1]
        new_lines += lines[end_index:]
        new_text = "\n".join(new_lines).rstrip() + "\n" if new_lines else ""
    owned_file = sha256_of(target) == state.get("files", {}).get("config.toml")
    delete_eligible = owned_file and not new_text.strip()
    if dry_run:
        if delete_eligible:
            status("DRY", "config.toml would be deleted (installer-created)")
        else:
            status("DRY", "config.toml owned keys would be removed")
        return "delete" if delete_eligible else "update"
    if delete_eligible:
        target.unlink()
        status("REMOVED", "config.toml")
        return "delete"
    write_text_utf8(target, new_text)
    status(
        "REMOVED",
        "config.toml [shell_environment_policy.set] owned keys "
        "(unrelated content preserved)",
    )
    return "update"


def remove_agents_block(codex_home, state, dry_run):
    """Remove the owned AGENTS.md block; returns a file outcome."""
    target = codex_home / "AGENTS.md"
    if not target.exists():
        return "absent"
    text = read_text_utf8(target)
    start_marker = f"<!-- {AGENTS_BLOCK_MARKER}:start -->"
    end_marker = f"<!-- {AGENTS_BLOCK_MARKER}:end -->"
    start_index = text.find(start_marker)
    if start_index < 0:
        status("OK", "AGENTS.md has no owned block")
        return "noop"
    end_index = text.find(end_marker, start_index)
    if end_index < 0:
        raise ValueError(f"AGENTS.md has a dangling {AGENTS_BLOCK_MARKER} start marker")
    end_of_line = text.find("\n", end_index)
    if end_of_line < 0:
        end_of_line = len(text)
    else:
        end_of_line += 1
    before = text[:start_index]
    after = text[end_of_line:]
    if before and not before.endswith("\n"):
        before += "\n"
    while after.startswith("\n"):
        after = after[1:]
    remainder = before + after
    new_text = remainder.rstrip() + "\n" if remainder.strip() else ""
    owned_file = sha256_of(target) == state.get("files", {}).get("AGENTS.md")
    delete_eligible = owned_file and not new_text.strip()
    if dry_run:
        if delete_eligible:
            status("DRY", "AGENTS.md would be deleted (installer-created)")
        else:
            status("DRY", "AGENTS.md owned block would be removed")
        return "delete" if delete_eligible else "update"
    if delete_eligible:
        target.unlink()
        status("REMOVED", "AGENTS.md")
        return "delete"
    write_text_utf8(target, new_text)
    status(
        "REMOVED",
        f"AGENTS.md {AGENTS_BLOCK_MARKER} block (unrelated content preserved)",
    )
    return "update"


def prune_owned_dirs(codex_home, dry_run):
    pruned = []
    for rel in OWNED_DIRS:
        directory = codex_home / rel
        if not directory.is_dir():
            continue
        if any(directory.iterdir()):
            continue
        if dry_run:
            status("DRY", f"empty directory {rel} would be pruned")
            pruned.append(rel)
            continue
        directory.rmdir()
        status("PRUNED", rel)
        pruned.append(rel)
    return pruned


def validate(codex_home):
    """Validate installed TOML/JSON; returns True only when everything parses."""
    checks = (
        (AGENT_FILENAME, tomllib.loads),
        ("config.toml", tomllib.loads),
        ("hooks.json", json.loads),
    )
    all_ok = True
    for rel, parser in checks:
        path = codex_home / rel
        if not path.exists():
            status("SKIP", f"validation skipped: {rel} does not exist")
            continue
        try:
            parser(read_text_utf8(path))
        except (tomllib.TOMLDecodeError, json.JSONDecodeError, UnicodeDecodeError) as error:
            status("FAIL", f"validation failed: {rel} ({error})")
            all_ok = False
    if all_ok:
        status("OK", "validation: TOML (agent, config) and JSON (hooks) all parse")
    return all_ok

def _plan_changes(codex_home, mode, python_executable, dry_run):
    """Compute planned writes (no writes); returns a dict with status lines.

    For ``mode == "add"`` the plan is strict and atomic: any managed artifact
    that already exists but would be changed by the add is a conflict. A
    conflicting add must write nothing and record no ownership.
    """
    writes = []
    conflicts = []
    hook_definition_changed = False
    agents_block_updated = False

    base_url, provider_lines, source = resolve_credentials(codex_home)

    def plan_whole(rel, data):
        target = codex_home / rel
        if not target.exists():
            if dry_run:
                status("DRY", f"{rel} would be written")
            writes.append((rel, data))
            return
        if target.read_bytes() == data:
            status("OK", f"{rel} unchanged")
            return
        if mode == "add":
            status(
                "CONFLICT",
                f"{rel} already present with different content; use --update to refresh",
            )
            conflicts.append(rel)
            return
        if dry_run:
            status("DRY", f"{rel} would be written")
        writes.append((rel, data))

    plan_whole(
        AGENT_FILENAME, agent_toml_content(base_url, provider_lines).encode("utf-8")
    )
    for payload_rel, dest_rel in PAYLOAD_DESTINATIONS.items():
        plan_whole(dest_rel, payload_bytes(payload_rel))
    plan_whole(
        "hooks/codex-deepseek-subagent/plaintext_handoff.py",
        payload_bytes("scripts/plaintext_handoff.py"),
    )

    # hooks.json (partial)
    replacement = hook_replacement_group(codex_home, python_executable)
    hooks_target = codex_home / "hooks.json"
    existing_doc = (
        json.loads(read_text_utf8(hooks_target)) if hooks_target.exists() else None
    )
    if existing_doc is not None and not isinstance(existing_doc, dict):
        raise ValueError("hooks.json must contain a top-level JSON object")
    new_doc, hook_changed, previous = merge_hooks(existing_doc, replacement)
    if mode == "add":
        if existing_doc is not None and hook_changed:
            status(
                "CONFLICT",
                "hooks.json exists and would change; use --update to refresh",
            )
            conflicts.append("hooks.json")
        elif hook_changed:
            if dry_run:
                status("DRY", "hooks.json would be written")
            writes.append(
                (
                    "hooks.json",
                    (
                        json.dumps(new_doc, ensure_ascii=False, indent=2) + "\n"
                    ).encode("utf-8"),
                )
            )
            hook_definition_changed = True
        else:
            status("OK", "hooks.json v4_flash_worker group unchanged")
    elif hook_changed:
        if dry_run:
            status("DRY", "hooks.json would be updated")
        writes.append(
            (
                "hooks.json",
                (
                    json.dumps(new_doc, ensure_ascii=False, indent=2) + "\n"
                ).encode("utf-8"),
            )
        )
        hook_definition_changed = True
    else:
        status("OK", "hooks.json unchanged")

    # config.toml (partial)
    config_target = codex_home / "config.toml"
    config_text = read_text_utf8(config_target) if config_target.exists() else ""
    config_new, config_changed = merge_config(config_text)
    if mode == "add":
        if config_target.exists() and config_changed:
            status(
                "CONFLICT",
                "config.toml exists and would change; use --update to refresh",
            )
            conflicts.append("config.toml")
        elif config_changed:
            if dry_run:
                status("DRY", "config.toml would set [shell_environment_policy.set]")
            writes.append(("config.toml", config_new.encode("utf-8")))
        else:
            status("OK", "config.toml [shell_environment_policy.set] unchanged")
    elif config_changed:
        if dry_run:
            status("DRY", "config.toml would set [shell_environment_policy.set]")
        writes.append(("config.toml", config_new.encode("utf-8")))
    else:
        status("OK", "config.toml [shell_environment_policy.set] unchanged")

    # AGENTS.md (partial)
    block = agents_block_text()
    agents_target = codex_home / "AGENTS.md"
    agents_text = read_text_utf8(agents_target) if agents_target.exists() else ""
    agents_new, agents_changed = merge_agents(agents_text, block)
    if mode == "add":
        if agents_target.exists() and agents_changed:
            status(
                "CONFLICT",
                "AGENTS.md exists and would change; use --update to refresh",
            )
            conflicts.append("AGENTS.md")
        elif agents_changed:
            if dry_run:
                status("DRY", "AGENTS.md would be written")
            writes.append(("AGENTS.md", agents_new.encode("utf-8")))
            agents_block_updated = True
        else:
            status("OK", "AGENTS.md unchanged")
    elif agents_changed:
        if dry_run:
            status("DRY", "AGENTS.md would be updated")
        writes.append(("AGENTS.md", agents_new.encode("utf-8")))
        agents_block_updated = True
    else:
        status("OK", "AGENTS.md unchanged")

    return {
        "writes": writes,
        "conflicts": conflicts,
        "hook_definition_changed": hook_definition_changed,
        "agents_block_updated": agents_block_updated,
        "source": source,
    }


def _execute_writes(codex_home, writes):
    for rel, data in writes:
        target = codex_home / rel
        write_bytes_atomically(target, data)
        if rel == AGENT_FILENAME and not is_windows():
            target.chmod(0o600)
        status("WROTE", rel)


def _save_installed_state(codex_home, python_executable, source):
    files = {}
    for rel in MANAGED_FILES:
        target = codex_home / rel
        if target.exists():
            files[rel] = sha256_of(target)
    state = {
        "format_version": 2,
        "tool": TOOL_NAME,
        "payload_version": PAYLOAD_VERSION,
        "installed_at": datetime.now(timezone.utc).isoformat(),
        "credential_source": source,
        "files": files,
        "hook_definition_sha256": hook_definition_sha256(
            hook_replacement_group(codex_home, python_executable)
        ),
        "config_owned_keys": list(ENVIRONMENT_VALUES),
        "agents_marker": AGENTS_BLOCK_MARKER,
    }
    save_state(codex_home, state)


def _rollback(codex_home, backup_dir):
    status("FAIL", "mutation failed; restoring the pre-change snapshot")
    try:
        restore_backup(backup_dir, codex_home, yes=True, force=True)
    except Exception as error:  # noqa: BLE001 - rollback must never mask the failure
        status(
            "FAIL",
            f"rollback itself failed ({error}); manual restore may be needed",
        )


def _run_install(args, action):
    codex_home = codex_home_from_env()
    python_executable = args.python_executable or sys.executable
    section(
        f"Codex home: {codex_home}  (platform: "
        f"{'windows' if is_windows() else 'posix'})"
    )
    try:
        plan = _plan_changes(codex_home, action, python_executable, args.dry_run)
    except Exception as error:  # noqa: BLE001 - report as a clean failure
        status("FAIL", f"planning failed: {error}")
        result = {
            "action": action,
            "codex_home": str(codex_home),
            "payload_version": PAYLOAD_VERSION,
            "changed": 0,
            "files_changed": [],
            "hook_definition_changed": False,
            "hook_review_required": False,
            "agents_block_updated": False,
            "credential_source": None,
            "backup_id": None,
            "error": f"planning failed: {error}",
            "exit_code": 1,
        }
        _emit_json(args, result)
        return 1

    writes = plan["writes"]
    source = plan["source"]

    if action == "add" and plan["conflicts"]:
        for rel in sorted(plan["conflicts"]):
            status("FAIL", f"{rel}: add conflict; nothing was written or owned")
        status(
            "FAIL",
            "--add is atomic and strict; resolve the conflicts or use --update",
        )
        result = {
            "action": action,
            "codex_home": str(codex_home),
            "payload_version": PAYLOAD_VERSION,
            "changed": 0,
            "files_changed": [],
            "conflicts": sorted(plan["conflicts"]),
            "hook_definition_changed": False,
            "hook_review_required": False,
            "agents_block_updated": False,
            "credential_source": source,
            "backup_id": None,
            "exit_code": 2,
        }
        _emit_json(args, result)
        return 2

    status("INFO", f"credential source: {source}")
    if "env var" in source:
        status(
            "WARN",
            "no API key provided; the worker will read DEEPSEEK_API_KEY from the "
            "Codex process environment at runtime",
        )

    backup_id = None
    if writes and not args.dry_run:
        backup_root = backup_root_from_args(args)
        if not args.skip_backup:
            try:
                backup_dir = create_backup(codex_home, backup_root, action=action)
            except Exception as error:  # noqa: BLE001 - report as a clean failure
                status(
                    "FAIL",
                    f"backup failed ({error}); nothing was written",
                )
                result = {
                    "action": action,
                    "codex_home": str(codex_home),
                    "payload_version": PAYLOAD_VERSION,
                    "changed": 0,
                    "files_changed": [],
                    "hook_definition_changed": plan["hook_definition_changed"],
                    "hook_review_required": plan["hook_definition_changed"],
                    "agents_block_updated": plan["agents_block_updated"],
                    "credential_source": source,
                    "backup_id": None,
                    "error": f"backup failed: {error}",
                    "exit_code": 1,
                }
                _emit_json(args, result)
                return 1
            backup_id = backup_dir.name
            status("BACKUP", f"pre-change snapshot saved to {backup_dir}")
        else:
            status("SKIP", "backup skipped (--skip-backup)")
        try:
            _execute_writes(codex_home, writes)
            _save_installed_state(codex_home, python_executable, source)
        except Exception as error:  # noqa: BLE001 - rollback is the recovery path
            status("FAIL", f"write failed ({error})")
            if backup_id is not None:
                _rollback(codex_home, backup_root / backup_id)
            result = {
                "action": action,
                "codex_home": str(codex_home),
                "payload_version": PAYLOAD_VERSION,
                "changed": 0,
                "files_changed": [],
                "hook_definition_changed": plan["hook_definition_changed"],
                "hook_review_required": plan["hook_definition_changed"],
                "agents_block_updated": plan["agents_block_updated"],
                "credential_source": source,
                "backup_id": backup_id,
                "exit_code": 1,
            }
            _emit_json(args, result)
            return 1
        section("Validation")
        if not validate(codex_home):
            status(
                "FAIL",
                "validation failed; rolling back the transaction (exit 1)",
            )
            if backup_id is not None:
                _rollback(codex_home, backup_root / backup_id)
            result = {
                "action": action,
                "codex_home": str(codex_home),
                "payload_version": PAYLOAD_VERSION,
                "changed": 0,
                "files_changed": [],
                "hook_definition_changed": plan["hook_definition_changed"],
                "hook_review_required": plan["hook_definition_changed"],
                "agents_block_updated": plan["agents_block_updated"],
                "credential_source": source,
                "backup_id": backup_id,
                "validation_failed": True,
                "exit_code": 1,
            }
            _emit_json(args, result)
            return 1
    elif writes:
        status("DRY", f"{len(writes)} file(s) would change; nothing was written")
    elif not args.dry_run:
        # Nothing needed writing; still surface pre-existing validation problems
        # instead of reporting a success on a broken install.
        section("Validation")
        if not validate(codex_home):
            result = {
                "action": action,
                "codex_home": str(codex_home),
                "payload_version": PAYLOAD_VERSION,
                "changed": 0,
                "files_changed": [],
                "hook_definition_changed": plan["hook_definition_changed"],
                "hook_review_required": plan["hook_definition_changed"],
                "agents_block_updated": plan["agents_block_updated"],
                "credential_source": source,
                "backup_id": None,
                "validation_failed": True,
                "exit_code": 1,
            }
            _emit_json(args, result)
            return 1

    applied = 0 if args.dry_run else len(writes)
    hook_review_required = plan["hook_definition_changed"]
    section("Summary")
    if args.dry_run and writes:
        status(
            "OK",
            f"dry run: {len(writes)} file(s) planned; nothing was written",
        )
    else:
        status("CHANGED" if applied else "OK", f"{applied} file(s) changed")
    if hook_review_required:
        status(
            "HOOK",
            "hook definition changed; review and trust it in Settings -> Hooks, "
            "then Refresh (restart only as fallback)",
        )
    else:
        status("OK", "hook definition unchanged; no new trust review needed")
    if plan["agents_block_updated"]:
        status("OK", "AGENTS.md codex-v4-flash-worker-agents block updated")

    result = {
        "action": action,
        "codex_home": str(codex_home),
        "payload_version": PAYLOAD_VERSION,
        "changed": applied,
        "files_changed": (
            [] if args.dry_run else sorted(rel for rel, _ in writes)
        ),
        "hook_definition_changed": hook_review_required,
        "hook_review_required": hook_review_required,
        "agents_block_updated": plan["agents_block_updated"],
        "credential_source": source,
        "backup_id": backup_id,
        "exit_code": 0,
    }
    if args.dry_run:
        result["dry_run"] = True
        result["planned_changes"] = len(writes)
        result["planned_files"] = sorted(rel for rel, _ in writes)
    _emit_json(args, result)
    return 0


def cmd_install(args):
    return _run_install(args, "install")


def cmd_add(args):
    return _run_install(args, "add")


def cmd_update(args):
    return _run_install(args, "update")


def cmd_backup(args):
    codex_home = codex_home_from_env()
    backup_root = backup_root_from_args(args)
    if args.dry_run:
        status("DRY", f"backup would be created under {backup_root}")
        result = {
            "action": "backup",
            "backup_id": None,
            "backup_dir": str(backup_root),
            "dry_run": True,
            "exit_code": 0,
        }
        _emit_json(args, result)
        return 0
    try:
        backup_dir = create_backup(codex_home, backup_root, action="backup")
    except Exception as error:  # noqa: BLE001 - report as a clean failure
        status("FAIL", f"backup failed ({error}); no snapshot was created")
        result = {
            "action": "backup",
            "backup_id": None,
            "backup_dir": str(backup_root),
            "error": f"backup failed: {error}",
            "exit_code": 1,
        }
        _emit_json(args, result)
        return 1
    status("BACKUP", f"snapshot saved to {backup_dir}")
    result = {
        "action": "backup",
        "backup_id": backup_dir.name,
        "backup_dir": str(backup_dir),
        "exit_code": 0,
    }
    _emit_json(args, result)
    return 0


def cmd_list_backups(args):
    backup_root = backup_root_from_args(args)
    backups = list_backups(backup_root)
    items = []
    for backup in backups:
        created_at = None
        manifest_path = backup / "manifest.json"
        if manifest_path.exists():
            try:
                created_at = json.loads(read_text_utf8(manifest_path)).get("created_at")
            except (json.JSONDecodeError, UnicodeDecodeError, OSError):
                pass
        items.append(
            {"id": backup.name, "path": str(backup), "created_at": created_at}
        )
    if args.json:
        print(
            json.dumps(
                {"action": "list-backups", "backups": items, "exit_code": 0},
                ensure_ascii=False,
                indent=2,
            )
        )
    else:
        if not items:
            status("OK", "no backups found")
        for item in items:
            status("BACKUP", f"{item['id']}  ({item['created_at'] or 'unknown'})")
    return 0


def cmd_status(args):
    codex_home = codex_home_from_env()
    state = load_state(codex_home)
    python_executable = args.python_executable or sys.executable
    backups = [backup.name for backup in list_backups(backup_root_from_args(args))]
    desired = hook_replacement_group(codex_home, python_executable)

    files_report = {}
    for rel in MANAGED_FILES:
        target = codex_home / rel
        entry = {"present": target.exists()}
        if target.exists():
            digest = sha256_of(target)
            entry["sha256"] = digest
            entry["owned"] = digest == state.get("files", {}).get(rel)
        files_report[rel] = entry

    current_group = None
    hooks_error = None
    hooks_target = codex_home / "hooks.json"
    if hooks_target.exists():
        try:
            document = json.loads(read_text_utf8(hooks_target))
            _validate_hooks_shape(document)
            for group in document.get("hooks", {}).get("SubagentStart", []):
                if (
                    isinstance(group, dict)
                    and group.get("matcher") == HOOK_GROUP_MATCHER
                ):
                    current_group = group
                    break
        except (
            json.JSONDecodeError,
            UnicodeDecodeError,
            OSError,
            ValueError,
        ) as error:
            hooks_error = str(error)
    # Compare the live Hook to the definition recorded at install time. The
    # recorded hash is interpreter-independent, so running status with a
    # different Python than the one used for the install cannot create a false
    # trust alert. Without a recorded hash (older state or nothing installed)
    # fall back to comparing against the payload-desired group.
    recorded_sha = state.get("hook_definition_sha256")
    if recorded_sha and current_group is not None:
        hook_definition_changed = (
            hook_definition_sha256(current_group) != recorded_sha
        )
    elif recorded_sha:
        hook_definition_changed = True
    else:
        hook_definition_changed = current_group != desired

    result = {
        "action": "status",
        "codex_home": str(codex_home),
        "payload_version": state.get("payload_version", PAYLOAD_VERSION),
        "installed": bool(state),
        "credential_source": state.get("credential_source"),
        "hooks_error": hooks_error,
        "hook_definition_changed": hook_definition_changed,
        "hook_review_required": hook_definition_changed,
        "files": files_report,
        "backups": backups,
        "exit_code": 0,
    }
    if args.json:
        print(json.dumps(result, ensure_ascii=False, indent=2))
    else:
        section("Status")
        status("HOME", str(codex_home))
        status("PAYLOAD", result["payload_version"])
        status("STATE", "installed" if state else "not installed")
        status("CREDENTIALS", state.get("credential_source") or "none recorded")
        for rel, entry in files_report.items():
            if not entry["present"]:
                mark, message = "MISSING", rel
            elif entry.get("owned"):
                mark, message = "OK", rel
            else:
                mark, message = "DRIFTED", f"{rel} (not owned by this installer)"
            status(mark, message)
        if hooks_error:
            status("FAIL", f"hooks.json is malformed ({hooks_error})")
        status(
            "HOOK",
            "definition changed; review required"
            if hook_definition_changed
            else "definition matches payload",
        )
        status("BACKUPS", ", ".join(backups) if backups else "none")
    return 0


def cmd_restore(args):
    codex_home = codex_home_from_env()
    backup_root = backup_root_from_args(args)
    backups = list_backups(backup_root)
    if not backups:
        status("FAIL", f"no backups found under {backup_root}")
        result = {
            "action": "restore",
            "backup_id": args.restore,
            "restored": [],
            "deleted": [],
            "skipped": [],
            "refused": [],
            "exit_code": 1,
        }
        _emit_json(args, result)
        return 1
    if args.restore and args.restore != "latest":
        matches = [backup for backup in backups if backup.name == args.restore]
        if not matches:
            status("FAIL", f"backup {args.restore} not found; available:")
            for backup in backups:
                status("BACKUP", backup.name)
            result = {
                "action": "restore",
                "backup_id": args.restore,
                "restored": [],
                "deleted": [],
                "skipped": [],
                "refused": [],
                "exit_code": 2,
            }
            _emit_json(args, result)
            return 2
        chosen = matches[0]
    else:
        chosen = backups[0]
        status("INFO", f"no ID given; using latest backup {chosen.name}")

    if args.dry_run:
        restore_backup(
            chosen, codex_home, yes=args.yes, force=args.force, dry_run=True
        )
        result = {
            "action": "restore",
            "backup_id": chosen.name,
            "restored": [],
            "deleted": [],
            "skipped": [],
            "refused": [],
            "dry_run": True,
            "exit_code": 0,
        }
        _emit_json(args, result)
        return 0

    _, refused, _ = _plan_restore(chosen, codex_home, args.yes, args.force)
    if refused:
        for rel in refused:
            status(
                "FAIL",
                f"{rel}: restore would clobber changed content; pass --yes "
                "(or --force) to restore anyway",
            )
        status("FAIL", "restore aborted; nothing was changed")
        result = {
            "action": "restore",
            "backup_id": chosen.name,
            "restored": [],
            "deleted": [],
            "skipped": [],
            "refused": refused,
            "exit_code": 2,
        }
        _emit_json(args, result)
        return 2

    safety_backup_id = None
    if not args.skip_backup:
        try:
            safety = create_backup(codex_home, backup_root, action="restore")
        except Exception as error:  # noqa: BLE001 - report as a clean failure
            status(
                "FAIL",
                f"safety backup failed ({error}); restore aborted, "
                "nothing was changed",
            )
            result = {
                "action": "restore",
                "backup_id": chosen.name,
                "restored": [],
                "deleted": [],
                "skipped": [],
                "refused": [],
                "error": f"safety backup failed: {error}",
                "exit_code": 1,
            }
            _emit_json(args, result)
            return 1
        safety_backup_id = safety.name
        status("BACKUP", f"pre-restore safety snapshot saved to {safety}")
    result = restore_backup(chosen, codex_home, yes=args.yes, force=args.force)
    result["action"] = "restore"
    result["backup_id"] = chosen.name
    result["safety_backup_id"] = safety_backup_id
    result["exit_code"] = 0
    _emit_json(args, result)
    return 0


def cmd_remove(args):
    codex_home = codex_home_from_env()
    section(
        f"Codex home: {codex_home}  (platform: "
        f"{'windows' if is_windows() else 'posix'})"
    )
    state = load_state(codex_home)
    if not args.dry_run and not args.yes:
        status(
            "FAIL",
            "--remove is destructive; pass --yes to confirm "
            "(or use --dry-run to preview)",
        )
        result = {
            "action": "remove",
            "removed_files": [],
            "kept_files": [],
            "pruned_dirs": [],
            "backup_id": None,
            "state_removed": False,
            "exit_code": 2,
        }
        _emit_json(args, result)
        return 2

    # A malformed hooks.json container must abort the whole removal before
    # any write so remove never partially mutates on a bad shape.
    hooks_target = codex_home / "hooks.json"
    if hooks_target.exists():
        try:
            _validate_hooks_shape(json.loads(read_text_utf8(hooks_target)))
        except (
            json.JSONDecodeError,
            UnicodeDecodeError,
            OSError,
            ValueError,
        ) as error:
            status(
                "FAIL",
                f"hooks.json is malformed ({error}); removal aborted, "
                "nothing was changed",
            )
            result = {
                "action": "remove",
                "removed_files": [],
                "kept_files": [],
                "pruned_dirs": [],
                "backup_id": None,
                "state_removed": False,
                "error": f"hooks.json is malformed: {error}",
                "exit_code": 1,
            }
            _emit_json(args, result)
            return 1

    backup_id = None
    if not args.dry_run and not args.skip_backup:
        try:
            backup_dir = create_backup(
                codex_home, backup_root_from_args(args), action="remove"
            )
        except Exception as error:  # noqa: BLE001 - report as a clean failure
            status(
                "FAIL",
                f"backup failed ({error}); nothing was removed",
            )
            result = {
                "action": "remove",
                "removed_files": [],
                "kept_files": [],
                "pruned_dirs": [],
                "backup_id": None,
                "state_removed": False,
                "error": f"backup failed: {error}",
                "exit_code": 1,
            }
            _emit_json(args, result)
            return 1
        backup_id = backup_dir.name
        status("BACKUP", f"pre-remove snapshot saved to {backup_dir}")

    removed_files = []
    kept_files = []
    for rel in WHOLE_MANAGED:
        target = codex_home / rel
        if not target.exists():
            continue
        owned = sha256_of(target) == state.get("files", {}).get(rel)
        if owned or args.force:
            if args.dry_run:
                status("DRY", f"{rel} would be removed")
            else:
                target.unlink()
                status("REMOVED", rel)
            removed_files.append(rel)
        else:
            kept_files.append(rel)
            status(
                "WARN",
                f"{rel} differs from installed state; keeping it (use --force to remove)",
            )

    for rel, outcome in (
        ("hooks.json", remove_hook_group(codex_home, state, args.dry_run)),
        ("config.toml", remove_config_owned(codex_home, state, args.dry_run)),
        ("AGENTS.md", remove_agents_block(codex_home, state, args.dry_run)),
    ):
        if outcome in ("delete", "update"):
            removed_files.append(rel)

    pruned_dirs = prune_owned_dirs(codex_home, args.dry_run)

    state_removed = False
    if not args.dry_run and state_dir(codex_home).exists():
        shutil.rmtree(state_dir(codex_home), ignore_errors=True)
        status("REMOVED", f"{STATE_DIR_NAME}/ state (installer ownership cleared)")
        state_removed = True

    result = {
        "action": "remove",
        "removed_files": sorted(set(removed_files)),
        "kept_files": sorted(set(kept_files)),
        "pruned_dirs": pruned_dirs,
        "backup_id": backup_id,
        "state_removed": state_removed,
        "exit_code": 0,
    }
    if args.dry_run:
        result["dry_run"] = True
    _emit_json(args, result)
    return 0


def main():
    try:
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    except (AttributeError, ValueError):
        pass

    parser = argparse.ArgumentParser(
        prog="codex-deepseek-subagent-setup",
        description=(
            "Cross-platform lifecycle installer for the Codex DeepSeek "
            "V4 Flash worker: add / update / backup / list-backups / status / "
            "restore / remove of the agent, skill payload, Hook, config, and "
            "AGENTS.md block. Backs up before every mutation. "
            "See --manual for the full manual."
        ),
        epilog=(
            "Examples:\n"
            "  python3 codex_deepseek_subagent_setup.py                 # install/upsert\n"
            "  python3 codex_deepseek_subagent_setup.py --add           # create missing only\n"
            "  python3 codex_deepseek_subagent_setup.py --update        # refresh owned content\n"
            "  python3 codex_deepseek_subagent_setup.py --backup        # snapshot now\n"
            "  python3 codex_deepseek_subagent_setup.py --list-backups  # list snapshot IDs\n"
            "  python3 codex_deepseek_subagent_setup.py --status --json # machine-readable state\n"
            "  python3 codex_deepseek_subagent_setup.py --restore       # restore latest\n"
            "  python3 codex_deepseek_subagent_setup.py --restore 20260809-123456-000000 --yes\n"
            "  python3 codex_deepseek_subagent_setup.py --remove --yes   # remove owned content\n"
            "  python3 codex_deepseek_subagent_setup.py --dry-run --remove\n"
            "  python3 codex_deepseek_subagent_setup.py --manual        # full manual"
        ),
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument(
        "--add", action="store_true",
        help="create missing artifacts only; never overwrite existing content",
    )
    parser.add_argument(
        "--update", action="store_true",
        help="refresh owned content to the payload; preserves an existing token",
    )
    parser.add_argument(
        "--backup", action="store_true",
        help="create a backup snapshot now",
    )
    parser.add_argument(
        "--list-backups", action="store_true",
        help="list backup IDs",
    )
    parser.add_argument(
        "--status", action="store_true",
        help="report per-file install/ownership state",
    )
    parser.add_argument(
        "--restore", nargs="?", const="latest", metavar="ID",
        help="restore from a backup ID (timestamp) or 'latest' (default)",
    )
    parser.add_argument(
        "--remove", action="store_true",
        help="remove installer-owned content (requires --yes)",
    )
    parser.add_argument(
        "--yes", action="store_true",
        help="confirm destructive actions (--restore/--remove)",
    )
    parser.add_argument(
        "--force", action="store_true",
        help="override ownership checks (drifted files, restore over changes)",
    )
    parser.add_argument(
        "--json", action="store_true",
        help="machine-readable JSON result on stdout (human lines go to stderr)",
    )
    parser.add_argument(
        "--dry-run", action="store_true",
        help="preview without writing or backing up anything",
    )
    parser.add_argument(
        "--backup-dir", default=str(default_backup_root()),
        help=f"backup directory (default: {default_backup_root()})",
    )
    parser.add_argument(
        "--skip-backup", action="store_true",
        help="do not create a pre-action backup snapshot",
    )
    parser.add_argument(
        "--codex-home", default=None,
        help="Codex home override (default: CODEX_HOME or ~/.codex)",
    )
    parser.add_argument(
        "--python-executable", default=None,
        help="Python executable for the Windows Hook commandWindows field "
        "(default: the interpreter running this script)",
    )
    parser.add_argument(
        "--manual", action="store_true",
        help="print the full manual and exit",
    )
    args = parser.parse_args()

    if args.codex_home:
        os.environ["CODEX_HOME"] = args.codex_home
    if args.json:
        global _OUTPUT_JSON
        _OUTPUT_JSON = True

    if args.manual:
        print(MANUAL)
        return 0

    actions = [
        name
        for name, active in (
            ("add", args.add),
            ("update", args.update),
            ("backup", args.backup),
            ("list-backups", args.list_backups),
            ("status", args.status),
            ("restore", args.restore is not None),
            ("remove", args.remove),
        )
        if active
    ]
    if len(actions) > 1:
        message = (
            f"conflicting actions: {', '.join(actions)}; choose exactly one"
        )
        if args.json:
            print(
                json.dumps(
                    {"error": message, "exit_code": 2},
                    ensure_ascii=False,
                    indent=2,
                )
            )
        else:
            print(f"error: {message}", file=sys.stderr)
        return 2

    if args.add:
        return cmd_add(args)
    if args.update:
        return cmd_update(args)
    if args.backup:
        return cmd_backup(args)
    if args.list_backups:
        return cmd_list_backups(args)
    if args.status:
        return cmd_status(args)
    if args.restore is not None:
        return cmd_restore(args)
    if args.remove:
        return cmd_remove(args)
    return cmd_install(args)


if __name__ == "__main__":
    sys.exit(main())
